parse:
{
  ...target,
  updatedBy: request.user?.username,
  title: target.title && Object.entries(target.title).map(([locale, value], index) => ({id: target.titleIds?.[index], locale, value})),
  body: target.body && Object.entries(target.body).map(([locale, value], index) => ({
    id: target.bodyIds?.[index],
    locale,
    value: sanitize(value, {
      PARSER_MEDIA_TYPE: 'application/xhtml+xml',
      ADD_TAGS: ['Component'],
      ADD_ATTR: ['resource', 'name', 'id']
    })
  }))
}

contents.options:
((currentLocale, defaultLocale) => ({
  select: {
    id: true
  },
  loadEagerRelations: false,
  relations: {
    title: true
  },
  where: {
    tags: {
      name: 'MENU',
      start: Raw(alias => `${alias} is null or ${alias} < :p1`, {p1: new Date()}),
      end: Raw(alias => `${alias} is null or ${alias} > :p2`, {p2: new Date()})
    },
    title: {
      locale: Or(Equal(currentLocale), Equal(defaultLocale))
    }
  }
}))(system.locale, Object.keys(settings.schema.locales)[0])

contents.projection:
((currentLocale, defaultLocale) => target.map(({id, title}) => ({
  id,
  title: title.find(({locale}) => locale === currentLocale)?.value || title.find(({locale}) => locale === defaultLocale)?.value
})))(system.locale, Object.keys(settings.schema.locales)[0])

contents.options:
((currentLocale, defaultLocale) => ({
  select: {
    id: true
  },
  loadEagerRelations: false,
  relations: {
    title: true,
    body: true
  },
  where: {
    id: request.query.id,
    tags: !request.user?.authorized && {
      name: 'PUBLISHED',
      start: Raw(alias => `${alias} is null or ${alias} < :p1`, {p1: new Date()}),
      end: Raw(alias => `${alias} is null or ${alias} > :p2`, {p2: new Date()})
    },
    title: {
      locale: Or(Equal(currentLocale), Equal(defaultLocale), IsNull())
    },
    body: {
      locale: Or(Equal(currentLocale), Equal(defaultLocale))
    }
  }
}))(system.locale, Object.keys(settings.schema.locales)[0])

contents.projection:
((currentLocale, defaultLocale) => ({
  title: target.title.find(({locale}) => locale === currentLocale)?.value || target.title.find(({locale}) => locale === defaultLocale)?.value,
  code: transform(target.body.find(({locale}) => locale === currentLocale)?.value || target.body.find(({locale}) => locale === defaultLocale)?.value)
}))(system.locale, Object.keys(settings.schema.locales)[0])
